import sys
import json
from os import path

sys.path.append(path.dirname(path.dirname(path.dirname(path.dirname(path.abspath(__file__))))))
import helper as hp


def get_fold_column_location(fold_id_list: list):
    """
    得到扣图上字符位置信息
    :param fold_id_list: 扣图id列表
    :return:
    """
    fold_column_list = []

    for tmp_fold_id in fold_id_list:
        fold_id = f"SX_{tmp_fold_id}"
        # 得到数据库链接
        db_work = hp.get_db('tw-work')
        # 443039代表思溪藏 name代表扣id
        cond2 = {'flag': 443039, 'name': fold_id}
        # 得到页信息
        page = db_work.page.find_one(cond2)
        columns = page.get("columns")
        column_list = []
        for column in columns:
            print(f'列开始位置={column.get("x")} 列宽={column.get("w")}')
            column_list.append({"x": column.get("x"), "w": column.get("w")})
        # 最左列宽横坐标及宽度
        sorted_column_list = sorted(column_list, key=lambda tmp: tmp.get("x"))
        max_left_column = sorted_column_list[0]
        # 最右列宽横坐标及宽度
        sorted_column_list = sorted(column_list, key=lambda tmp: tmp.get("x"), reverse=True)
        max_right_column = sorted_column_list[0]
        fold_column_list.append({"fold_id": tmp_fold_id, "max_left_column": max_left_column, "max_right_column": max_right_column})
    with open("need_delete_bold_edge_fold_column_list.json", "w") as f:
        f.write(json.dumps(fold_column_list))


